-- The tables of a seed's EasyLog.db, as the service served them. Schema only, no data.
CREATE TABLE "SickDesc" ("ID" TEXT PRIMARY KEY  NOT NULL  UNIQUE , "Timestamp" REAL DEFAULT 0 ,  "Name" TEXT NOT NULL UNIQUE , "Description" TEXT);
CREATE TABLE "BathDesc" ("ID" TEXT PRIMARY KEY  NOT NULL  UNIQUE , "Timestamp" REAL DEFAULT 0 ,  "Name" TEXT NOT NULL UNIQUE , "Description" TEXT);
CREATE TABLE "SleepDesc" ("ID" TEXT PRIMARY KEY  NOT NULL  UNIQUE , "Timestamp" REAL DEFAULT 0 ,  "Name" TEXT NOT NULL UNIQUE , "Description" TEXT);
CREATE TABLE "FeedDesc" ("ID" TEXT PRIMARY KEY  NOT NULL  UNIQUE , "Timestamp" REAL DEFAULT 0 ,  "Name" TEXT NOT NULL UNIQUE , "Description" TEXT);
CREATE TABLE "OtherActivityDesc" ("ID" TEXT PRIMARY KEY  NOT NULL  UNIQUE , "Timestamp" REAL DEFAULT 0 ,  "Name" TEXT NOT NULL UNIQUE , "Description" TEXT);
CREATE TABLE "MilestoneSelection" ("ID" TEXT PRIMARY KEY  NOT NULL  UNIQUE , "Timestamp" REAL DEFAULT 0 ,  "Name" TEXT NOT NULL UNIQUE , "Description" TEXT , "ForAge" INTEGER, "BabyID" TEXT);
CREATE TABLE "DoctorSelection" ("ID" TEXT PRIMARY KEY  NOT NULL  UNIQUE , "Timestamp" REAL DEFAULT 0 ,  "Name" TEXT NOT NULL UNIQUE , "Description" TEXT, "Address" TEXT, "ClinicName" TEXT, "PhoneNumber" TEXT);
CREATE TABLE "MedicineSelection" ("ID" TEXT PRIMARY KEY  NOT NULL  UNIQUE , "Timestamp" REAL DEFAULT 0 ,  "Name" TEXT NOT NULL UNIQUE , "Description" TEXT, "IsPrescription" INTEGER, "AmountPerTime" REAL, "Unit" TEXT, "Interval" INTEGER);
CREATE TABLE "VaccineSelection" ("ID" TEXT PRIMARY KEY  NOT NULL  UNIQUE , "Timestamp" REAL DEFAULT 0 ,  "Name" TEXT NOT NULL UNIQUE , "Description" TEXT , "ForAge" INTEGER);
CREATE TABLE "OtherFeedSelection" ("ID" TEXT PRIMARY KEY  NOT NULL  UNIQUE , "Timestamp" REAL DEFAULT 0 ,  "Name" TEXT NOT NULL UNIQUE , "Description" TEXT , "IsBottle" INTEGER);
CREATE TABLE "AllergenSourceSelection" ("ID" TEXT PRIMARY KEY  NOT NULL  UNIQUE , "Timestamp" REAL DEFAULT 0 ,  "Name" TEXT NOT NULL UNIQUE , "Description" TEXT);
CREATE TABLE "SleepLocationSelection" ("ID" TEXT PRIMARY KEY  NOT NULL  UNIQUE , "Timestamp" REAL DEFAULT 0 ,  "Name" TEXT NOT NULL UNIQUE , "Description" TEXT);
CREATE TABLE "OtherActivityLocationSelection" ("ID" TEXT PRIMARY KEY  NOT NULL  UNIQUE , "Timestamp" REAL DEFAULT 0 ,  "Name" TEXT NOT NULL UNIQUE , "Description" TEXT);
CREATE TABLE "Baby" ("ID" TEXT PRIMARY KEY  NOT NULL  UNIQUE , "Timestamp" REAL DEFAULT 0 ,  "Name" TEXT NOT NULL UNIQUE , "DOB" REAL , "DueDay" REAL , "Gender" INTEGER , "Picture" TEXT);
CREATE TABLE "Picture" ("ID" TEXT PRIMARY KEY  NOT NULL  UNIQUE , "Timestamp" REAL DEFAULT 0 ,  "ActivityID" TEXT NOT NULL, "Type" INTEGER , "FileName" TEXT NOT NULL, "Thumbnail" BLOB);
CREATE TABLE "Pump" ("ID" TEXT PRIMARY KEY  NOT NULL  UNIQUE , "Timestamp" REAL DEFAULT 0 ,  "Time" REAL NOT NULL, "Note" TEXT, "HasPicture" INTEGER, "FinishSide" INTEGER, "Sides" INTEGER, "Amount" REAL, "IsEnglishScale" INTEGER, "Label" TEXT, "PumpedID" TEXT, 'LeftAmount' REAL DEFAULT 0, 'RightAmount' REAL DEFAULT 0, 'LeftDuration' INTEGER DEFAULT 0, 'RightDuration' INTEGER DEFAULT 0);
CREATE TABLE "Milestone" ("ID" TEXT PRIMARY KEY  NOT NULL  UNIQUE , "Timestamp" REAL DEFAULT 0 ,  "Time" REAL NOT NULL, "Note" TEXT, "HasPicture" INTEGER, "BabyID" TEXT NOT NULL, "MilestoneSelectionID" TEXT NOT NULL);
CREATE TABLE "OtherActivity" ("ID" TEXT PRIMARY KEY  NOT NULL  UNIQUE , "Timestamp" REAL DEFAULT 0 ,  "Time" REAL NOT NULL, "Note" TEXT, "HasPicture" INTEGER, "BabyID" TEXT NOT NULL, "DescID" TEXT, "LocationID" TEXT, "Duration" INTEGER);
CREATE TABLE "Bath" ("ID" TEXT PRIMARY KEY  NOT NULL  UNIQUE , "Timestamp" REAL DEFAULT 0 ,  "Time" REAL NOT NULL, "Note" TEXT, "HasPicture" INTEGER, "BabyID" TEXT NOT NULL, "DescID" TEXT);
CREATE TABLE "Diaper" ("ID" TEXT PRIMARY KEY  NOT NULL  UNIQUE , "Timestamp" REAL DEFAULT 0 ,  "Time" REAL NOT NULL, "Note" TEXT, "HasPicture" INTEGER, "BabyID" TEXT NOT NULL, "Status" INTEGER NOT NULL, "PeeColor" INTEGER DEFAULT 5, "PooColor" INTEGER DEFAULT 5, "Amount" INTEGER DEFAULT 5, "Texture" INTEGER DEFAULT 5, "Flag" INTEGER DEFAULT 0);
CREATE TABLE "Sleep" ("ID" TEXT PRIMARY KEY  NOT NULL  UNIQUE , "Timestamp" REAL DEFAULT 0 ,  "Time" REAL NOT NULL, "Note" TEXT, "HasPicture" INTEGER, "BabyID" TEXT NOT NULL, "Duration" INTEGER DEFAULT 0, "LocationID" TEXT, "DescID" TEXT);
CREATE TABLE "Nursing" ("ID" TEXT PRIMARY KEY  NOT NULL  UNIQUE , "Timestamp" REAL DEFAULT 0 ,  "Time" REAL NOT NULL, "Note" TEXT, "HasPicture" INTEGER, "BabyID" TEXT NOT NULL, "DescID" TEXT, "FinishSide" INTEGER, "LeftDuration" INTEGER DEFAULT 0, "RightDuration" INTEGER DEFAULT 0, "BothDuration" INTEGER DEFAULT 0);
CREATE TABLE "OtherFeed" ("ID" TEXT PRIMARY KEY  NOT NULL  UNIQUE , "Timestamp" REAL DEFAULT 0 ,  "Time" REAL NOT NULL, "Note" TEXT, "HasPicture" INTEGER, "BabyID" TEXT NOT NULL, "DescID" TEXT, "TypeID" TEXT NOT NULL, "Amount" REAL DEFAULT 0, "IsEnglishScale" INTEGER DEFAULT 0, "Unit" TEXT);
CREATE TABLE "Pumped" ("ID" TEXT PRIMARY KEY  NOT NULL  UNIQUE , "Timestamp" REAL DEFAULT 0 ,  "Time" REAL NOT NULL, "Note" TEXT, "HasPicture" INTEGER, "BabyID" TEXT NOT NULL, "DescID" TEXT, "Amount" REAL NOT NULL, "IsEnglishScale" INTEGER NOT NULL, "PumpID" TEXT);
CREATE TABLE "Formula" ("ID" TEXT PRIMARY KEY  NOT NULL  UNIQUE , "Timestamp" REAL DEFAULT 0 ,  "Time" REAL NOT NULL, "Note" TEXT, "HasPicture" INTEGER, "BabyID" TEXT NOT NULL, "DescID" TEXT, "Amount" REAL NOT NULL, "IsEnglishScale" INTEGER NOT NULL);
CREATE TABLE "Temperature" ("ID" TEXT PRIMARY KEY  NOT NULL  UNIQUE , "Timestamp" REAL DEFAULT 0 ,  "Time" REAL NOT NULL, "Note" TEXT, "HasPicture" INTEGER, "BabyID" TEXT NOT NULL, "Temp" REAL NOT NULL, "IsEnglishScale" INTEGER NOT NULL);
CREATE TABLE "Allergen" ("ID" TEXT PRIMARY KEY  NOT NULL  UNIQUE , "Timestamp" REAL DEFAULT 0 ,  "Time" REAL NOT NULL, "Note" TEXT, "HasPicture" INTEGER, "BabyID" TEXT NOT NULL, "SourceID" TEXT NOT NULL, "Reaction" TEXT, "Severity" INTEGER NOT NULL, "NotSure" INTEGER DEFAULT 0);
CREATE TABLE "HealthQuestion" ("ID" TEXT PRIMARY KEY  NOT NULL  UNIQUE , "Timestamp" REAL DEFAULT 0 ,  "Time" REAL NOT NULL, "Note" TEXT, "HasPicture" INTEGER, "BabyID" TEXT NOT NULL, "Question" TEXT NOT NULL, "Answer" TEXT, "DoctorVisitID" TEXT);
CREATE TABLE "Medicine" ("ID" TEXT PRIMARY KEY  NOT NULL  UNIQUE , "Timestamp" REAL DEFAULT 0 ,  "Time" REAL NOT NULL, "Note" TEXT, "HasPicture" INTEGER, "BabyID" TEXT NOT NULL, "MedID" TEXT NOT NULL, "Amount" REAL);
CREATE TABLE "Vaccine" ("ID" TEXT PRIMARY KEY  NOT NULL  UNIQUE , "Timestamp" REAL DEFAULT 0 ,  "Time" REAL NOT NULL, "Note" TEXT, "HasPicture" INTEGER, "BabyID" TEXT NOT NULL, "VaccID" TEXT NOT NULL, "DocVisitID" TEXT NOT NULL);
CREATE TABLE "Sick" ("ID" TEXT PRIMARY KEY  NOT NULL  UNIQUE , "Timestamp" REAL DEFAULT 0 ,  "Time" REAL NOT NULL, "Note" TEXT, "HasPicture" INTEGER, "BabyID" TEXT NOT NULL, "Symptom" TEXT);
CREATE TABLE "Growth" ("ID" TEXT PRIMARY KEY  NOT NULL  UNIQUE , "Timestamp" REAL DEFAULT 0 ,  "Time" REAL NOT NULL, "Note" TEXT, "HasPicture" INTEGER, "BabyID" TEXT NOT NULL, "Weight" REAL DEFAULT 0, "Length" REAL DEFAULT 0, "Head" READ DEFAULT 0, "IsEnglishLengthScale" INTEGER DEFAULT 1, "IsEnglishWeightScale" INTEGER DEFAULT 1);
CREATE TABLE "DoctorVisit" ("ID" TEXT PRIMARY KEY  NOT NULL  UNIQUE , "Timestamp" REAL DEFAULT 0 ,  "Time" REAL NOT NULL, "Note" TEXT, "HasPicture" INTEGER, "BabyID" TEXT NOT NULL, "IsAppointment" INTEGER NOT NULL, "VisitType" INTEGER DEFAULT 0, "DoctorID" TEXT, "DoctorNote" TEXT, "Symptom" TEXT, "GrowthID" TEXT, "SickID" TEXT);
CREATE TABLE "DoctorVisitMedicine" ("ID" TEXT PRIMARY KEY  NOT NULL  UNIQUE , "Timestamp" REAL DEFAULT 0 ,  "DoctorVisitID" TEXT NOT NULL, "MedID" TEXT NOT NULL);
CREATE TABLE "Joy" ("ID" TEXT PRIMARY KEY  NOT NULL  UNIQUE , "Timestamp" REAL DEFAULT 0 ,  "Time" REAL NOT NULL, "Note" TEXT, "HasPicture" INTEGER, "BabyID" TEXT NOT NULL);
CREATE TABLE "Journal" ("ID" TEXT PRIMARY KEY  NOT NULL  UNIQUE , "Timestamp" REAL DEFAULT 0 ,  "Time" REAL NOT NULL, "Note" TEXT, "HasPicture" INTEGER, "BabyID" TEXT NOT NULL);
CREATE TABLE 'TransactionLog' ('ID' INTEGER PRIMARY KEY AUTOINCREMENT, 'OpCode' INTEGER NOT NULL, 'Log' BLOB NOT NULL);
CREATE TABLE 'PhotoList' ('PhotoFile' TEXT PRIMARY KEY NOT NULL UNIQUE);
CREATE TABLE 'PhotoDownloadList' ('PhotoFile' TEXT PRIMARY KEY NOT NULL UNIQUE, 'DownloadCount' INTEGER DEFAULT 0);
CREATE TABLE 'MergedTransaction' ('DeviceID' TEXT PRIMARY KEY  NOT NULL  UNIQUE, 'SyncID' INTEGER);
CREATE TABLE 'ReliveList' ('ID' TEXT PRIMARY KEY NOT NULL UNIQUE);
CREATE TABLE Progress (BabyID TEXT NOT NULL, ProgressType INTEGER NOT NULL, ProgressID TEXT NOT NULL, ProgressTime REAL NOT NULL, ProgressValue REAL NOT NULL, PRIMARY KEY(BabyID, ProgressType));
CREATE TABLE ProgressPump (ProgressType INTEGER PRIMARY KEY NOT NULL UNIQUE, ProgressID TEXT NOT NULL, ProgressTime REAL NOT NULL, ProgressValue REAL NOT NULL);
